from email.errors import HeaderParseError
from email.header import Header
from email.headerregistry import Address, parser

def punycode(domain):
    return domain.encode('idna').decode('ascii')

def sanitize_address(addr, encoding):
    address = None
    if not isinstance(addr, tuple):
        addr = str(addr)
        try:
            token, rest = parser.get_mailbox(addr)
        except (HeaderParseError, ValueError, IndexError):
            raise ValueError('Invalid address "%s"' % addr)
        else:
            if rest:
                raise ValueError(
                    'Invalid address; only %s could be parsed from "%s"' % (token, addr)
                )
            nm = token.display_name or ''
            localpart = token.local_part
            domain = token.domain or ''
    else:
        nm, address = addr
        localpart, domain = address.rsplit('@', 1)

    nm = Header(nm, encoding).encode()
    try:
        localpart.encode('ascii')
    except UnicodeEncodeError:
        localpart = Header(localpart, encoding).encode()
    domain = punycode(domain)

    parsed_address = Address(nm, username=localpart, domain=domain)
    return str(parsed_address)

# Valid cases
valid = [
    ('to@example.com', 'ascii', 'to@example.com'),
    ('to@example.com', 'utf-8', 'to@example.com'),
    (('A name', 'to@example.com'), 'ascii', 'A name <to@example.com>'),
    (('A name', 'to@example.com'), 'utf-8', '=?utf-8?q?A_name?= <to@example.com>'),
    ('localpartonly', 'ascii', 'localpartonly'),
    ('A name <to@example.com>', 'ascii', 'A name <to@example.com>'),
    ('A name <to@example.com>', 'utf-8', '=?utf-8?q?A_name?= <to@example.com>'),
    ('"A name" <to@example.com>', 'ascii', 'A name <to@example.com>'),
    ('"A name" <to@example.com>', 'utf-8', '=?utf-8?q?A_name?= <to@example.com>'),
    ('tó@example.com', 'utf-8', '=?utf-8?b?dMOz?=@example.com'),
    ('to@éxample.com', 'utf-8', 'to@xn--xample-9ua.com'),
    (('Tó Example', 'tó@example.com'), 'utf-8', '=?utf-8?q?T=C3=B3_Example?= <=?utf-8?b?dMOz?=@example.com>'),
    ('Tó Example <tó@example.com>', 'utf-8', '=?utf-8?q?T=C3=B3_Example?= <=?utf-8?b?dMOz?=@example.com>'),
    ('To Example <to@éxample.com>', 'ascii', 'To Example <to@xn--xample-9ua.com>'),
    ('To Example <to@éxample.com>', 'utf-8', '=?utf-8?q?To_Example?= <to@xn--xample-9ua.com>'),
    ('"to@other.com"@example.com', 'utf-8', r'"to@other.com"@example.com'),
    ('"to@other.com" <to@example.com>', 'utf-8', '=?utf-8?q?to=40other=2Ecom?= <to@example.com>'),
    (('To Example', 'to@other.com@example.com'), 'utf-8', '=?utf-8?q?To_Example?= <"to@other.com"@example.com>'),
]

for ea, enc, exp in valid:
    try:
        got = sanitize_address(ea, enc)
    except Exception as e:
        print(f"VALID-FAIL {ea!r} {enc}: raised {type(e).__name__}: {e}")
    else:
        status = "OK" if got == exp else "DIFF"
        print(f"{status} {ea!r} {enc}: got={got!r} exp={exp!r}")

print("---- invalid ----")
